import React, { useEffect, useMemo, useRef, useState } from "react";
import styled from "styled-components";
import useRemoteSession from "./useRemoteSession";
import {
  EVENT_TYPES,
  HEARTBEAT_INTERVAL_MS,
  POINTER_THROTTLE_MS,
  makeEnvelope,
} from "./eventProtocol";

const Wrapper = styled.div`
  max-width: 560px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 12px;
`;

const Card = styled.div`
  background: rgba(15, 20, 27, 0.92);
  border: 1px solid rgba(127, 161, 232, 0.3);
  border-radius: 10px;
  padding: 12px;
  color: #f2f6ff;
`;

const Label = styled.label`
  display: block;
  font-size: 0.86rem;
  margin-bottom: 6px;
  color: rgba(255, 255, 255, 0.78);
`;

const Input = styled.input`
  width: 100%;
  border-radius: 8px;
  border: 1px solid rgba(127, 161, 232, 0.4);
  background: rgba(9, 11, 15, 0.9);
  color: #fff;
  padding: 10px;
  font-size: 1.1rem;
  letter-spacing: 0.18em;
`;

const Touchpad = styled.div`
  user-select: none;
  touch-action: none;
  height: 300px;
  border-radius: 12px;
  border: 1px solid rgba(127, 161, 232, 0.45);
  background: radial-gradient(circle at 30% 20%, rgba(127, 161, 232, 0.2), rgba(10, 12, 16, 1));
  display: grid;
  place-items: center;
  color: rgba(255, 255, 255, 0.8);
  font-size: 1rem;
`;

const Row = styled.div`
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
`;

const Button = styled.button`
  border: 1px solid rgba(127, 161, 232, 0.4);
  color: #fff;
  border-radius: 8px;
  padding: 8px 12px;
  background: ${p => (p.$active ? "rgba(127,161,232,0.45)" : "rgba(127,161,232,0.2)")};
  cursor: pointer;
`;

const Status = styled.p`
  margin: 6px 0 0;
  font-size: 0.88rem;
  color: ${p => (p.$error ? "#ff9cae" : "rgba(255,255,255,0.8)")};
`;

const COLORS = ["#7fa1e8", "#e47da6", "#74d49b", "#ffd370", "#ffffff"];

const ControllerPanel = ({ sid }) => {
  const clientId = useMemo(() => `controller_${Math.random().toString(36).slice(2, 10)}`, []);
  const [pairCode, setPairCode] = useState("");
  const [isJoined, setIsJoined] = useState(false);
  const [joinError, setJoinError] = useState("");
  const [drawMode, setDrawMode] = useState(false);
  const [color, setColor] = useState(COLORS[0]);
  const [size, setSize] = useState(4);
  const lastPosRef = useRef(null);
  const drawingRef = useRef(false);
  const lastSendRef = useRef(0);

  const { status, error, sendEnvelope } = useRemoteSession({
    sid,
    enabled: Boolean(sid),
    onEvent: payload => {
      if (payload?.type !== EVENT_TYPES.JOIN_ACK) return;
      if (payload?.targetClientId !== clientId) return;

      if (payload.accepted) {
        setIsJoined(true);
        setJoinError("");
      } else {
        setIsJoined(false);
        const reason = payload.reason?.replaceAll("_", " ") || "join rejected";
        setJoinError(reason);
      }
    },
  });

  useEffect(() => {
    if (!isJoined) return undefined;
    const id = setInterval(() => {
      sendEnvelope(makeEnvelope({ sid, type: EVENT_TYPES.HEARTBEAT, clientId }));
    }, HEARTBEAT_INTERVAL_MS);
    return () => clearInterval(id);
  }, [clientId, isJoined, sendEnvelope, sid]);

  const sendJoinRequest = () => {
    if (!pairCode || pairCode.length !== 6) {
      setJoinError("Enter the 6-digit code shown on desktop");
      return;
    }
    setJoinError("");
    sendEnvelope(
      makeEnvelope({
        sid,
        type: EVENT_TYPES.JOIN_REQUEST,
        clientId,
        payload: { code: pairCode },
      })
    );
  };

  const getPoint = event => {
    const target = event.currentTarget;
    const rect = target.getBoundingClientRect();
    const source = event.touches ? event.touches[0] : event;
    return {
      x: source.clientX - rect.left,
      y: source.clientY - rect.top,
      nx: (source.clientX - rect.left) / rect.width,
      ny: (source.clientY - rect.top) / rect.height,
    };
  };

  const sendDelta = (dx, dy, type) => {
    const now = Date.now();
    if (now - lastSendRef.current < POINTER_THROTTLE_MS) return;
    lastSendRef.current = now;
    sendEnvelope(makeEnvelope({ sid, type, clientId, payload: { dx, dy } }));
  };

  const handlePointerDown = event => {
    if (!isJoined) return;
    event.preventDefault();
    const p = getPoint(event);
    lastPosRef.current = p;

    if (drawMode) {
      drawingRef.current = true;
      sendEnvelope(
        makeEnvelope({
          sid,
          type: EVENT_TYPES.DRAW_START,
          clientId,
          payload: { x: p.nx, y: p.ny, color, size },
        })
      );
    }
  };

  const handlePointerMove = event => {
    if (!isJoined) return;
    if (!lastPosRef.current) return;
    event.preventDefault();

    const p = getPoint(event);
    const dx = p.x - lastPosRef.current.x;
    const dy = p.y - lastPosRef.current.y;
    lastPosRef.current = p;

    if (drawMode && drawingRef.current) {
      sendDelta(dx, dy, EVENT_TYPES.DRAW_MOVE);
      return;
    }

    if (!drawMode) {
      sendDelta(dx, dy, EVENT_TYPES.POINTER_DELTA);
    }
  };

  const handlePointerUp = event => {
    if (!isJoined) return;
    event.preventDefault();

    if (drawMode && drawingRef.current) {
      sendEnvelope(makeEnvelope({ sid, type: EVENT_TYPES.DRAW_END, clientId }));
    }

    drawingRef.current = false;
    lastPosRef.current = null;
  };

  if (!sid) {
    return <Status $error>Missing session id. Re-scan the QR code from desktop.</Status>;
  }

  return (
    <Wrapper>
      <Card>
        <Label htmlFor="pair-code">Enter 6-digit pairing code</Label>
        <Input
          id="pair-code"
          inputMode="numeric"
          autoComplete="one-time-code"
          maxLength={6}
          value={pairCode}
          onChange={e => setPairCode(e.target.value.replace(/\D/g, ""))}
        />
        <Row style={{ marginTop: 10 }}>
          <Button type="button" onClick={sendJoinRequest}>Pair</Button>
          <Button type="button" $active={drawMode} onClick={() => setDrawMode(v => !v)}>
            {drawMode ? "Draw mode" : "Trackpad mode"}
          </Button>
        </Row>
        <Status>Realtime: {status || "idle"}</Status>
        {joinError ? <Status $error>{joinError}</Status> : null}
        {error ? <Status $error>{error}</Status> : null}
      </Card>

      <Card>
        <Touchpad
          onMouseDown={handlePointerDown}
          onMouseMove={handlePointerMove}
          onMouseUp={handlePointerUp}
          onMouseLeave={handlePointerUp}
          onTouchStart={handlePointerDown}
          onTouchMove={handlePointerMove}
          onTouchEnd={handlePointerUp}
        >
          {drawMode ? "Draw on desktop canvas" : "Move finger to control desktop cursor"}
        </Touchpad>
      </Card>

      <Card>
        <Row>
          {COLORS.map(next => (
            <Button key={next} type="button" $active={next === color} onClick={() => setColor(next)} style={{ background: next === color ? next : "rgba(127,161,232,0.2)", color: next === "#ffffff" ? "#111" : "#fff" }}>
              {next === color ? "Selected" : "Color"}
            </Button>
          ))}
        </Row>
        <Label htmlFor="size-slider" style={{ marginTop: 10 }}>Brush size: {size}px</Label>
        <input id="size-slider" type="range" min="2" max="12" value={size} onChange={e => setSize(Number(e.target.value))} />
        <Row style={{ marginTop: 10 }}>
          <Button type="button" onClick={() => sendEnvelope(makeEnvelope({ sid, type: EVENT_TYPES.ACTIVITY_ACTION, clientId, payload: { action: "clear" } }))}>Clear</Button>
          <Button type="button" onClick={() => sendEnvelope(makeEnvelope({ sid, type: EVENT_TYPES.ACTIVITY_ACTION, clientId, payload: { action: "undo" } }))}>Undo</Button>
        </Row>
      </Card>
    </Wrapper>
  );
};

export default ControllerPanel;
