import React, { useEffect, useMemo, useRef } from "react";
import styled from "styled-components";

const StageShell = styled.div`
  background: rgba(13, 15, 17, 0.95);
  border: 1px solid rgba(127, 161, 232, 0.32);
  border-radius: 10px;
  padding: 12px;
`;

const StageCanvas = styled.canvas`
  width: min(860px, 92vw);
  height: min(520px, 56vw);
  display: block;
  border-radius: 8px;
  border: 1px solid rgba(127, 161, 232, 0.2);
  background: linear-gradient(180deg, #0b0d10 0%, #11161f 100%);
`;

const Metrics = styled.div`
  margin-top: 10px;
  display: flex;
  gap: 18px;
  color: rgba(255, 255, 255, 0.74);
  font-size: 0.85rem;

  span {
    color: #7fa1e8;
    font-weight: 600;
  }
`;

const drawGrid = (ctx, width, height) => {
  ctx.strokeStyle = "rgba(127,161,232,0.08)";
  ctx.lineWidth = 1;
  const gap = 28;
  for (let x = 0; x <= width; x += gap) {
    ctx.beginPath();
    ctx.moveTo(x, 0);
    ctx.lineTo(x, height);
    ctx.stroke();
  }
  for (let y = 0; y <= height; y += gap) {
    ctx.beginPath();
    ctx.moveTo(0, y);
    ctx.lineTo(width, y);
    ctx.stroke();
  }
};

const drawPath = (ctx, points, color, size) => {
  if (!points?.length) return;

  if (points.length === 1) {
    const p = points[0];
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.arc(p.x, p.y, size / 2, 0, Math.PI * 2);
    ctx.fill();
    return;
  }

  ctx.strokeStyle = color;
  ctx.lineWidth = size;
  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  ctx.beginPath();
  ctx.moveTo(points[0].x, points[0].y);
  for (let i = 1; i < points.length; i += 1) {
    ctx.lineTo(points[i].x, points[i].y);
  }
  ctx.stroke();
};

const CanvasStage = ({ paths, currentPath, pointer, size }) => {
  const canvasRef = useRef(null);
  const pathCount = useMemo(() => paths.length + (currentPath ? 1 : 0), [paths.length, currentPath]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const dpr = typeof window !== "undefined" ? window.devicePixelRatio || 1 : 1;
    canvas.width = Math.floor(size.width * dpr);
    canvas.height = Math.floor(size.height * dpr);

    const ctx = canvas.getContext("2d");
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

    ctx.clearRect(0, 0, size.width, size.height);
    drawGrid(ctx, size.width, size.height);

    paths.forEach(path => drawPath(ctx, path.points, path.color, path.size));
    if (currentPath) drawPath(ctx, currentPath.points, currentPath.color, currentPath.size);

    ctx.fillStyle = "#e47da6";
    ctx.strokeStyle = "rgba(255,255,255,0.9)";
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(pointer.x, pointer.y, 6, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
  }, [paths, currentPath, pointer.x, pointer.y, size.height, size.width]);

  return (
    <StageShell>
      <StageCanvas ref={canvasRef} />
      <Metrics>
        <div>
          Strokes: <span>{pathCount}</span>
        </div>
        <div>
          Cursor: <span>{Math.round(pointer.x)}×{Math.round(pointer.y)}</span>
        </div>
      </Metrics>
    </StageShell>
  );
};

export default CanvasStage;
