export const REMOTE_EVENT = "remote_event";

export const EVENT_TYPES = {
  JOIN_REQUEST: "join_request",
  JOIN_ACK: "join_ack",
  POINTER_DELTA: "pointer_delta",
  DRAW_START: "draw_start",
  DRAW_MOVE: "draw_move",
  DRAW_END: "draw_end",
  ACTIVITY_ACTION: "activity_action",
  HEARTBEAT: "heartbeat",
};

export const SESSION_TTL_MS = 10 * 60 * 1000;
export const HEARTBEAT_INTERVAL_MS = 5000;
export const HEARTBEAT_TIMEOUT_MS = 15000;
export const POINTER_THROTTLE_MS = 16;
export const DELTA_CLAMP_PX = 40;

export const createSessionId = () => {
  const random = Math.random().toString(36).slice(2, 10);
  return `sid_${Date.now().toString(36)}_${random}`;
};

export const createPairCode = () => `${Math.floor(100000 + Math.random() * 900000)}`;

export const now = () => Date.now();

export const isExpired = expiresAt => now() > expiresAt;

export const clampDelta = value => {
  if (Number.isNaN(value) || !Number.isFinite(value)) return 0;
  return Math.max(-DELTA_CLAMP_PX, Math.min(DELTA_CLAMP_PX, value));
};

export const normalizeHostPath = path => {
  if (!path) return "/remote-lab";
  return path.endsWith("/") ? `${path}remote-lab` : `${path}/remote-lab`;
};

export const createChannelName = sid => `remote:${sid}`;

export const makeEnvelope = ({ sid, type, clientId, payload = {} }) => ({
  sid,
  type,
  clientId,
  t: now(),
  ...payload,
});
