import React, { useMemo, useState } from "react";
import styled from "styled-components";
import { QRCodeSVG } from "qrcode.react";

const Card = styled.div`
  background: rgba(15, 20, 27, 0.92);
  border: 1px solid rgba(127, 161, 232, 0.36);
  border-radius: 10px;
  padding: 14px;
  color: #f2f6ff;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
`;

const PairCode = styled.div`
  font-size: 1.8rem;
  letter-spacing: 0.2em;
  font-weight: 700;
  color: #7fa1e8;
`;

const Tiny = styled.p`
  margin: 0;
  color: rgba(255, 255, 255, 0.74);
  text-align: center;
  font-size: 0.83rem;
`;

const Row = styled.div`
  display: flex;
  gap: 8px;
`;

const Button = styled.button`
  border: 1px solid rgba(127, 161, 232, 0.38);
  color: #fff;
  border-radius: 6px;
  padding: 6px 10px;
  background: rgba(127, 161, 232, 0.2);
  cursor: pointer;
`;

const PairingCard = ({ pairCode, qrUrl, expiresAt }) => {
  const [copyLabel, setCopyLabel] = useState("Copy Link");
  const expiresLabel = useMemo(() => {
    const mins = Math.max(0, Math.ceil((expiresAt - Date.now()) / 60000));
    return `${mins} min`;
  }, [expiresAt]);

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(qrUrl);
      setCopyLabel("Copied");
      setTimeout(() => setCopyLabel("Copy Link"), 1400);
    } catch (error) {
      setCopyLabel("Copy failed");
      setTimeout(() => setCopyLabel("Copy Link"), 1400);
    }
  };

  return (
    <Card>
      <QRCodeSVG value={qrUrl} size={188} bgColor="#ffffff" fgColor="#1b2636" level="M" includeMargin />
      <Tiny>Scan from your phone and enter this pairing code.</Tiny>
      <PairCode>{pairCode}</PairCode>
      <Tiny>Session expires in {expiresLabel}.</Tiny>
      <Row>
        <Button type="button" onClick={handleCopy}>{copyLabel}</Button>
        <Button type="button" as="a" href={qrUrl} target="_blank" rel="noreferrer">Open Controller</Button>
      </Row>
    </Card>
  );
};

export default PairingCard;
