import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import styled from "styled-components";
import PairingCard from "./PairingCard";
import CanvasStage from "./CanvasStage";
import useRemoteSession from "./useRemoteSession";
import {
  EVENT_TYPES,
  HEARTBEAT_TIMEOUT_MS,
  SESSION_TTL_MS,
  clampDelta,
  createPairCode,
  createSessionId,
  isExpired,
  makeEnvelope,
} from "./eventProtocol";

const PANEL_WIDTH = { width: 860, height: 520 };
const COLORS = ["#7fa1e8", "#e47da6", "#74d49b", "#ffd370", "#ffffff"];

const Wrapper = styled.div`
  display: grid;
  grid-template-columns: minmax(240px, 280px) 1fr;
  gap: 16px;
  align-items: start;

  @media (max-width: 980px) {
    grid-template-columns: 1fr;
  }
`;

const Sidebar = styled.aside`
  display: flex;
  flex-direction: column;
  gap: 12px;
`;

const Card = styled.div`
  background: rgba(15, 20, 27, 0.92);
  border: 1px solid rgba(127, 161, 232, 0.3);
  border-radius: 10px;
  padding: 12px;
  color: #f2f6ff;
`;

const Title = styled.h3`
  margin: 0 0 8px;
  font-size: 0.95rem;
  color: rgba(255, 255, 255, 0.86);
`;

const StatusLine = styled.div`
  font-size: 0.85rem;
  color: ${p => (p.$ok ? "#7ff0c8" : "rgba(255,255,255,0.72)")};
  margin: 5px 0;
`;

const ButtonRow = styled.div`
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-top: 8px;
`;

const Button = styled.button`
  border: 1px solid rgba(127, 161, 232, 0.38);
  color: #fff;
  border-radius: 6px;
  padding: 7px 10px;
  background: rgba(127, 161, 232, 0.2);
  cursor: pointer;
`;

const ColorSwatch = styled.button`
  width: 22px;
  height: 22px;
  border-radius: 50%;
  border: 2px solid ${p => (p.$active ? "#ffffff" : "rgba(255,255,255,0.2)")};
  background: ${p => p.$color};
  cursor: pointer;
`;

const Range = styled.input`
  width: 100%;
  accent-color: #7fa1e8;
`;

const clampPoint = (value, max) => Math.max(0, Math.min(max, value));

const createHostSession = () => ({
  sid: createSessionId(),
  pairCode: createPairCode(),
  expiresAt: Date.now() + SESSION_TTL_MS,
});

const LOCAL_HOSTS = new Set(["localhost", "127.0.0.1", "0.0.0.0"]);

const HostPanel = () => {
  const [session, setSession] = useState(createHostSession);
  const [pointer, setPointer] = useState({ x: PANEL_WIDTH.width / 2, y: PANEL_WIDTH.height / 2 });
  const [paths, setPaths] = useState([]);
  const [currentPath, setCurrentPath] = useState(null);
  const [connectedControllerId, setConnectedControllerId] = useState("");
  const [lastHeartbeatAt, setLastHeartbeatAt] = useState(0);
  const [color, setColor] = useState(COLORS[0]);
  const [brushSize, setBrushSize] = useState(4);
  const [clockTick, setClockTick] = useState(Date.now());
  const smoothRef = useRef({ dx: 0, dy: 0 });

  const [controllerBaseUrl, setControllerBaseUrl] = useState("");

  useEffect(() => {
    let alive = true;

    const resolveBaseUrl = async () => {
      const envBase = process.env.GATSBY_REMOTE_LAB_BASE_URL;
      if (envBase) {
        if (alive) setControllerBaseUrl(envBase.replace(/\/+$/, ""));
        return;
      }

      if (typeof window === "undefined") return;

      const { hostname, port, protocol, origin } = window.location;
      if (!LOCAL_HOSTS.has(hostname)) {
        if (alive) setControllerBaseUrl(origin);
        return;
      }

      try {
        const response = await fetch("https://api.ipify.org?format=json", { cache: "no-store" });
        if (!response.ok) throw new Error("ipify request failed");
        const data = await response.json();
        if (!data?.ip) throw new Error("ipify response missing ip");

        const url = `${protocol}//${data.ip}${port ? `:${port}` : ""}`;
        if (alive) setControllerBaseUrl(url);
      } catch (error) {
        if (alive) setControllerBaseUrl(origin);
      }
    };

    resolveBaseUrl();
    return () => {
      alive = false;
    };
  }, []);

  const qrUrl = useMemo(() => {
    if (!controllerBaseUrl) return "";
    return `${controllerBaseUrl}/remote-lab?mode=controller&sid=${session.sid}`;
  }, [controllerBaseUrl, session.sid]);

  const controllerOnline = useMemo(
    () => Boolean(connectedControllerId) && clockTick - lastHeartbeatAt < HEARTBEAT_TIMEOUT_MS,
    [clockTick, connectedControllerId, lastHeartbeatAt]
  );

  useEffect(() => {
    const id = setInterval(() => setClockTick(Date.now()), 1000);
    return () => clearInterval(id);
  }, []);

  useEffect(() => {
    if (!connectedControllerId) return;
    if (clockTick - lastHeartbeatAt >= HEARTBEAT_TIMEOUT_MS) {
      setConnectedControllerId("");
    }
  }, [clockTick, connectedControllerId, lastHeartbeatAt]);

  const resetPointer = useCallback(() => {
    setPointer({ x: PANEL_WIDTH.width / 2, y: PANEL_WIDTH.height / 2 });
    smoothRef.current = { dx: 0, dy: 0 };
  }, []);

  const restartSession = useCallback(() => {
    setSession(createHostSession());
    setConnectedControllerId("");
    setLastHeartbeatAt(0);
    setPaths([]);
    setCurrentPath(null);
    resetPointer();
  }, [resetPointer]);

  const updatePointerFromDelta = useCallback((dxRaw, dyRaw) => {
    const smoothedDx = smoothRef.current.dx * 0.35 + clampDelta(dxRaw) * 0.65;
    const smoothedDy = smoothRef.current.dy * 0.35 + clampDelta(dyRaw) * 0.65;
    smoothRef.current = { dx: smoothedDx, dy: smoothedDy };

    setPointer(prev => ({
      x: clampPoint(prev.x + smoothedDx * 1.35, PANEL_WIDTH.width),
      y: clampPoint(prev.y + smoothedDy * 1.35, PANEL_WIDTH.height),
    }));
  }, []);

  const { status, error, sendEnvelope } = useRemoteSession({
    sid: session.sid,
    onEvent: payload => {
      if (!payload?.type || payload.sid !== session.sid) return;

      if (payload.type === EVENT_TYPES.JOIN_REQUEST) {
        const codeOk = payload.code === session.pairCode;
        const expired = isExpired(session.expiresAt);
        const alreadyPaired = Boolean(connectedControllerId && connectedControllerId !== payload.clientId);

        let accepted = true;
        let reason = "";
        if (expired) {
          accepted = false;
          reason = "session_expired";
        } else if (!codeOk) {
          accepted = false;
          reason = "invalid_code";
        } else if (alreadyPaired) {
          accepted = false;
          reason = "controller_already_connected";
        }

        if (accepted) {
          setConnectedControllerId(payload.clientId);
          setLastHeartbeatAt(Date.now());
        }

        sendEnvelope(
          makeEnvelope({
            sid: session.sid,
            type: EVENT_TYPES.JOIN_ACK,
            clientId: "host",
            payload: { accepted, reason, targetClientId: payload.clientId },
          })
        );
        return;
      }

      if (!connectedControllerId || payload.clientId !== connectedControllerId) return;

      if (payload.type === EVENT_TYPES.HEARTBEAT) {
        setLastHeartbeatAt(Date.now());
        return;
      }

      if (payload.type === EVENT_TYPES.POINTER_DELTA) {
        updatePointerFromDelta(payload.dx, payload.dy);
        return;
      }

      if (payload.type === EVENT_TYPES.DRAW_START) {
        setLastHeartbeatAt(Date.now());
        setPointer(prev => {
          const next = {
            x: typeof payload.x === "number" ? clampPoint(payload.x * PANEL_WIDTH.width, PANEL_WIDTH.width) : prev.x,
            y: typeof payload.y === "number" ? clampPoint(payload.y * PANEL_WIDTH.height, PANEL_WIDTH.height) : prev.y,
          };
          setCurrentPath({ points: [next], color: payload.color || color, size: payload.size || brushSize });
          return next;
        });
        return;
      }

      if (payload.type === EVENT_TYPES.DRAW_MOVE) {
        setPointer(prev => {
          const next = {
            x: clampPoint(prev.x + clampDelta(payload.dx) * 1.35, PANEL_WIDTH.width),
            y: clampPoint(prev.y + clampDelta(payload.dy) * 1.35, PANEL_WIDTH.height),
          };
          setCurrentPath(path => (path ? { ...path, points: [...path.points, next] } : path));
          return next;
        });
        return;
      }

      if (payload.type === EVENT_TYPES.DRAW_END) {
        setCurrentPath(path => {
          if (path?.points?.length) setPaths(prev => [...prev, path]);
          return null;
        });
        return;
      }

      if (payload.type === EVENT_TYPES.ACTIVITY_ACTION) {
        if (payload.action === "clear") {
          setPaths([]);
          setCurrentPath(null);
        }
        if (payload.action === "undo") {
          setPaths(prev => prev.slice(0, -1));
        }
      }
    },
  });

  const manualDisconnect = () => {
    if (connectedControllerId) {
      sendEnvelope(
        makeEnvelope({
          sid: session.sid,
          type: EVENT_TYPES.JOIN_ACK,
          clientId: "host",
          payload: { accepted: false, reason: "disconnected_by_host", targetClientId: connectedControllerId },
        })
      );
    }
    setConnectedControllerId("");
    setLastHeartbeatAt(0);
  };

  return (
    <Wrapper>
      <Sidebar>
        <PairingCard pairCode={session.pairCode} qrUrl={qrUrl} expiresAt={session.expiresAt} />

        <Card>
          <Title>Session</Title>
          <StatusLine>Realtime status: {status || "idle"}</StatusLine>
          <StatusLine $ok={controllerOnline}>Controller: {controllerOnline ? "Connected" : connectedControllerId ? "Inactive" : "Waiting"}</StatusLine>
          <StatusLine>Session ID: {session.sid.slice(-10)}</StatusLine>
          <ButtonRow>
            <Button type="button" onClick={restartSession}>New Session</Button>
            <Button type="button" onClick={manualDisconnect}>Disconnect</Button>
          </ButtonRow>
        </Card>

        <Card>
          <Title>Draw Tools</Title>
          <ButtonRow>
            {COLORS.map(next => (
              <ColorSwatch key={next} type="button" $color={next} $active={next === color} onClick={() => setColor(next)} />
            ))}
          </ButtonRow>
          <StatusLine>Brush: {brushSize}px</StatusLine>
          <Range type="range" min="2" max="12" value={brushSize} onChange={e => setBrushSize(Number(e.target.value))} />
          <ButtonRow>
            <Button type="button" onClick={() => { setPaths([]); setCurrentPath(null); }}>Clear</Button>
            <Button type="button" onClick={() => setPaths(prev => prev.slice(0, -1))}>Undo</Button>
          </ButtonRow>
        </Card>

        {error ? <Card><StatusLine>{error}</StatusLine></Card> : null}
      </Sidebar>

      <CanvasStage paths={paths} currentPath={currentPath} pointer={pointer} size={PANEL_WIDTH} />
    </Wrapper>
  );
};

export default HostPanel;
